import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"生民","description":"","frontmatter":{"title":"生民","date":"2026-11-09T00:00:00.000Z","seq":11,"categories":["美文","诗经"],"collection":"《诗经 · 大雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·大雅/生民.md","filePath":"blogs/诗经·大雅/生民.md"}'),o={name:"blogs/诗经·大雅/生民.md"};function c(l,a,n,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="生民" tabindex="-1">生民 <a class="header-anchor" href="#生民" aria-label="Permalink to &quot;生民&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　生民之什</p><div class="poem"><p class="poem-stanza">厥初生民，时维姜嫄。生民如何？克禋克祀，以弗无子。</p><p class="poem-stanza">履帝武敏歆，攸介攸止，载震载夙。载生载育，时维后稷。</p><p class="poem-stanza">诞弥厥月，先生如达。不拆不副，无菑无害。以赫厥灵。</p><p class="poem-stanza">上帝不宁，不康禋祀，居然生子。</p><p class="poem-stanza">诞寘之隘巷，牛羊腓字之。诞寘之平林，会伐平林。</p><p class="poem-stanza">诞寘之寒冰，鸟覆翼之。鸟乃去矣，后稷呱矣。</p><p class="poem-stanza">实覃实訏，厥声载路。诞实匍匐，克岐克嶷。以就口食。</p><p class="poem-stanza">蓺之荏菽，荏菽旆旆。禾役穟穟，麻麦幪幪，瓜瓞唪唪。</p><p class="poem-stanza">诞后稷之穑，有相之道。茀厥丰草，种之黄茂。实方实苞，实种实褎。</p><p class="poem-stanza">实发实秀，实坚实好。实颖实栗，即有邰家室。</p><p class="poem-stanza">诞降嘉种，维秬维秠，维穈维芑。恒之秬秠，是获是亩。</p><p class="poem-stanza">恒之穈芑，是任是负。以归肇祀。</p><p class="poem-stanza">诞我祀如何？或舂或揄，或簸或蹂。释之叟叟，烝之浮浮。</p><p class="poem-stanza">载谋载惟。取萧祭脂，取羝以軷，载燔载烈，以兴嗣岁。</p><p class="poem-stanza">卬盛于豆，于豆于登。其香始升，上帝居歆。胡臭亶时。</p><p class="poem-stanza">后稷肇祀。庶无罪悔，以迄于今。</p></div>',3)])])}const z=s(o,[["render",c]]);export{d as __pageData,z as default};
